const files = $input.all().map(i => i.json);
const c = files.filter(f => {
  const n = (f.name || '').toUpperCase();
  return n.includes('BC') && (n.includes('TÀI') || n.includes('TAI') || n.includes('T_I'));
});
if (c.length === 0) throw new Error('Không tìm thấy file BC_TÀI_CHÍNH trong Drive');
c.sort((a, b) => new Date(b.modifiedTime) - new Date(a.modifiedTime));
return [{ json: { fileId: c[0].id, fileName: c[0].name, modifiedTime: c[0].modifiedTime } }];

// Parse XLSX → cash/lead/expense/revenue (carry-forward số dư đầu ngày)
const XLSX = require('xlsx');
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const wb = XLSX.read(buf, { type: 'buffer', cellDates: false });

const num = (v) => { if (v==null||v==='') return 0; if (typeof v==='number') return v; const n=parseFloat(String(v).replace(/[^0-9.-]/g,'')); return isNaN(n)?0:n; };
const getCell = (s, r) => { const c = s[r]; return c ? c.v : null; };
function parseSheetDate(sn){ const s=(sn||'').trim(); if(s.toUpperCase().includes('TỔNG')||s.toUpperCase().includes('TONG')) return null; const m=s.match(/^(\d{1,2})(\d)$/); if(!m) return null; const day=parseInt(m[1],10), month=parseInt(m[2],10); if(day<1||day>31||month<1||month>12) return null; return {day,month,iso:`2026-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}; }
function hashRow(...p){ const str=p.map(x=>String(x??'')).join('|'); let h=0; for(let i=0;i<str.length;i++){h=((h<<5)-h)+str.charCodeAt(i); h|=0;} return Math.abs(h).toString(36); }
function mapCat(note){ const n=String(note||'').toLowerCase();
  if(n.includes('lương')||n.includes('luong')) return 'Lương NV';
  if(n.includes('thuê')||n.includes('thue nha')) return 'Thuê nhà';
  if(n.includes('điện')||n.includes('nước')||n.includes('mạng')||n.includes('rác')) return 'Điện nước';
  if(n.includes('vật tư')||n.includes('vat tu')) return 'Vật tư';
  if(n.includes('bảo hiểm')||n.includes('bao hiem')) return 'Bảo hiểm';
  if(n.includes('fb ads')||n.includes('gg ads')||n.includes('quảng cáo')) return 'Quảng cáo';
  if(n.includes('ncc')||n.includes('nhà cung cấp')) return 'Mua hàng NCC';
  if(n.includes('ship')) return 'Vận chuyển';
  if(n.includes('chuyển')||n.includes('rút')||n.includes('chuyen')||n.includes('rut')) return 'Chuyển-Rút';
  if(n.includes('hoàn')||n.includes('hoan')) return 'Hoàn KH';
  return 'Khác'; }

const days=[];
for(const sn of wb.SheetNames){ const d=parseSheetDate(sn); if(d) days.push({sn,d}); }
days.sort((a,b)=> (a.d.month-b.d.month) || (a.d.day-b.d.day));

const cashRecords=[], leadRecords=[], expenseRecords=[], revenueRecords=[];
const allISO=[];
let prevPK=0, prevCTY=0;
for(const {sn,d} of days){
  const ws=wb.Sheets[sn]; if(!ws) continue;
  allISO.push(d.iso);
  const ngayText=`${String(d.day).padStart(2,'0')}/${String(d.month).padStart(2,'0')}/2026`;
  const H1=num(getCell(ws,'H1')), M1=num(getCell(ws,'M1'));
  const B3=num(getCell(ws,'B3')), B17=num(getCell(ws,'B17'));
  const tkPKCuoi=H1+M1-B17, tkCTYCuoi=B17;
  let tongRa=0;
  for(let r=14;r<=26;r++){ tongRa+=num(getCell(ws,`H${r}`)); tongRa+=num(getCell(ws,`M${r}`)); }
  cashRecords.push({ ngayText, ngayISO:d.iso, tkPKDau:prevPK, tkPKCuoi, tkCTYDau:prevCTY, tkCTYCuoi, tongVao:B3, tongRa });
  prevPK=tkPKCuoi; prevCTY=tkCTYCuoi;

  const fb=num(getCell(ws,'I29')),yt=num(getCell(ws,'J29')),gg=num(getCell(ws,'K29')),cu=num(getCell(ws,'L29')),kh=num(getCell(ws,'M29'));
  if(fb+yt+gg+cu+kh>0) leadRecords.push({ ngayText, ngayISO:d.iso, facebook:fb, youtube:yt, google:gg, khCu:cu, khac:kh });

  for(let r=14;r<=26;r++){
    const amt=num(getCell(ws,`H${r}`)); if(amt<=0) continue;
    const code=getCell(ws,`I${r}`), note=getCell(ws,`J${r}`); const cat=mapCat(note);
    expenseRecords.push({ mota:`${cat} ${d.iso} #${r}-NH`, ngayISO:d.iso, hangMuc:cat, soTien:amt, phuongThuc:'Chuyển khoản', taiKhoan:'TK Phòng Khám', ghiChu:String(note||'').trim(), hash:hashRow(d.iso,'NH',r,amt,code,note) });
  }
  for(let r=14;r<=26;r++){
    const amt=num(getCell(ws,`M${r}`)); if(amt<=0) continue;
    const code=getCell(ws,`N${r}`), note=getCell(ws,`O${r}`), note2=getCell(ws,`P${r}`); const cat=mapCat(note);
    expenseRecords.push({ mota:`${cat} ${d.iso} #${r}-TM`, ngayISO:d.iso, hangMuc:cat, soTien:amt, phuongThuc:'Tiền mặt', taiKhoan:'TK Phòng Khám', ghiChu:[note,note2].filter(Boolean).map(s=>String(s).trim()).join(' | '), hash:hashRow(d.iso,'TM',r,amt,code,note) });
  }

  const rDT=num(getCell(ws,'C5')), rDV=num(getCell(ws,'C6'));
  if(rDT>0) revenueRecords.push({ mota:`Khóa học ${d.iso}`, ngayISO:d.iso, sale:'Chung', loai:'Khóa học', soTien:rDT, hash:hashRow(d.iso,'REV','DT',rDT) });
  if(rDV>0) revenueRecords.push({ mota:`Dịch vụ & mỹ phẩm ${d.iso}`, ngayISO:d.iso, sale:'Chung', loai:'Dịch vụ', soTien:rDV, hash:hashRow(d.iso,'REV','DV',rDV) });
}
const minISO = allISO.length ? allISO[0] : '2026-01-01';
const maxISO = allISO.length ? allISO[allISO.length-1] : '2026-12-31';
return [{ json: { summary:{ cashCount:cashRecords.length, leadCount:leadRecords.length, expenseCount:expenseRecords.length, revenueCount:revenueRecords.length }, minISO, maxISO, cashRecords, leadRecords, expenseRecords, revenueRecords } }];

const ids=[];
for(const name of ['Query Old Cash','Query Old Revenue','Query Old Expenses']){
  const res=$(name).first().json.results||[];
  for(const p of res) ids.push(p.id);
}
if(ids.length===0) return [{ json:{ pageId:'__none__' } }];
return ids.map(id=>({ json:{ pageId:id } }));

const d = $('Parse XLSX').first().json;
const out=[];
for(const r of d.cashRecords) out.push({ json:{ kind:'cash', ...r } });
for(const r of d.leadRecords) out.push({ json:{ kind:'lead', ...r } });
for(const r of d.expenseRecords) out.push({ json:{ kind:'expense', ...r } });
for(const r of d.revenueRecords) out.push({ json:{ kind:'revenue', ...r } });
return out;

